<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { jointStore as store, PEOPLE, clone, displayTime } from '../../data/equipmentInspectionMock.js'
import TaskResults from './TaskResults.vue'
import InspectionExecution from './InspectionExecution.vue'
const route=useRoute(),personId=ref('person-01'),scope=ref('mine')
const filters=ref({text:'',status:'',result:'',date:''}),applied=ref(clone(filters.value)),page=ref(1)
const rows=computed(()=>store.state.tasks.filter(row=>(scope.value!=='mine' || row.personId===personId.value) && (!applied.value.text || `${row.code}${row.planName}`.includes(applied.value.text)) && (!applied.value.status || row.status===applied.value.status) && (!applied.value.result || store.taskSummary(row)===applied.value.result) && (!applied.value.date || row.date===applied.value.date)).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.slot.start.localeCompare(a.slot.start)))
const mine=computed(()=>store.state.tasks.filter(row=>row.personId===personId.value))
function query(){applied.value=clone(filters.value);applied.value.text=applied.value.text.trim();page.value=1}
function reset(){filters.value={text:'',status:'',result:'',date:''};query()}
const detailId=ref(''),mobile=ref(false),mobileTaskId=ref('')
const detail=computed(()=>store.byId(store.state.tasks,detailId.value))
watch(()=>route.query.task,id=>{if(id)detailId.value=String(id)},{immediate:true})
watch([personId,scope],()=>page.value=1)
function execute(id=''){mobileTaskId.value=id;mobile.value=true}
const resultTone=result=>result==='存在异常'?'danger':result==='未见异常'?'success':'info'
</script>
<template>
  <main class="inspection-page"><header class="heading"><div><div class="eyebrow">巡检管理 / 现场执行</div><h1>巡检任务</h1><p class="subtitle">一张任务、多个检查点。按对象填写，异常如实保存，完成与正常分别表达。</p></div><el-button type="primary" @click="execute()">我的任务 · 移动预览</el-button></header><p class="demo-note">本地 Mock 演示 · 内置样本固定在 2026-10-28 / 29，新增任务从计划“模拟生成”。不接入真实调度、扫码、IoT、AI、工单或消息推送。</p><el-alert v-if="store.notice.persistence" :title="store.notice.persistence" type="warning" :closable="false" />
    <div class="count-strip"><span><strong>{{ mine.filter(row=>row.status==='待执行').length }}</strong> 我的待执行</span><span><strong>{{ mine.filter(row=>row.status==='进行中').length }}</strong> 进行中</span><span><strong>{{ mine.filter(row=>row.status==='已完成').length }}</strong> 已完成</span><span><strong>{{ mine.filter(row=>store.taskSummary(row)==='存在异常').length }}</strong> 存在异常</span></div>
    <section class="panel"><div class="filters"><span>演示执行身份</span><el-select v-model="personId" aria-label="演示执行身份"><el-option v-for="person in PEOPLE" :key="person.id" :value="person.id" :label="person.name" /></el-select><el-radio-group v-model="scope" aria-label="任务范围"><el-radio-button value="mine">我的任务</el-radio-button><el-radio-button value="all">全部任务</el-radio-button></el-radio-group></div>
      <el-form class="filters" @submit.prevent="query"><el-input v-model="filters.text" aria-label="任务查询" placeholder="任务编号 / 计划名称" clearable /><el-select v-model="filters.status" aria-label="任务执行状态" placeholder="全部执行状态" clearable><el-option v-for="status in ['待执行','进行中','已完成']" :key="status" :value="status" /></el-select><el-select v-model="filters.result" aria-label="任务检查结果" placeholder="全部检查结果" clearable><el-option v-for="result in ['未检查','未见异常','存在异常','未自动判定']" :key="result" :value="result" /></el-select><el-date-picker v-model="filters.date" aria-label="任务日期" type="date" value-format="YYYY-MM-DD" placeholder="计划日期" style="width:170px" /><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <el-table :data="rows.slice((page-1)*10,page*10)" stripe empty-text="当前身份或筛选条件下没有任务"><el-table-column label="任务 / 来源计划" min-width="235"><template #default="{row}"><el-button link type="primary" class="title-button" @click="detailId=row.id">{{ row.planName }}</el-button><div class="muted">{{ row.code }}</div><el-tag v-if="row.seeded" type="info" size="small">内置演示样本</el-tag></template></el-table-column><el-table-column label="计划时间 / 执行人" min-width="175"><template #default="{row}">{{ row.date }}<div>{{ row.slot.start }}—{{ row.slot.end }}</div><div class="muted">{{ row.personName }}</div></template></el-table-column><el-table-column label="检查点 / 必检进度" min-width="145"><template #default="{row}">{{ store.progress(row).completePoints }} / {{ row.points.length }} 点<div class="muted">必检 {{ store.progress(row).requiredFilled }} / {{ store.progress(row).requiredTotal }} 项</div></template></el-table-column><el-table-column label="执行 / 结果 / 时间" min-width="170"><template #default="{row}"><el-tag :type="row.status==='已完成'?'success':row.status==='进行中'?'primary':'info'">{{ row.status }}</el-tag><div class="tag-line"><el-tag :type="resultTone(store.taskSummary(row))" size="small">{{ store.taskSummary(row) }}</el-tag><el-tag :type="store.timeStatus(row)==='未超期'?'info':'warning'" size="small">{{ store.timeStatus(row) }}</el-tag></div></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detailId=row.id">详情</el-button><el-button v-if="row.status!=='已完成'" link type="primary" :disabled="row.personId!==personId" @click="execute(row.id)">{{ row.status==='进行中'?'继续检查':'移动执行' }}</el-button><router-link v-else :to="{path:'/inspection/records',query:{task:row.id}}"><el-button link>记录</el-button></router-link></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="rows.length" layout="total, prev, pager, next" class="pagination" /></section>
    <el-drawer :model-value="Boolean(detail)" title="巡检任务与原始结果" size="min(900px,94vw)" append-to-body @close="detailId=''"><template v-if="detail"><h2>{{ detail.planName }}</h2><div class="tag-line"><el-tag>{{ detail.status }}</el-tag><el-tag :type="resultTone(store.taskSummary(detail))">{{ store.taskSummary(detail) }}</el-tag><el-tag :type="store.timeStatus(detail)==='未超期'?'info':'warning'">{{ store.timeStatus(detail) }}</el-tag></div><dl class="detail-list"><dt>任务编号</dt><dd>{{ detail.code }}{{ detail.seeded?'（内置模拟样本）':'' }}</dd><dt>来源计划</dt><dd>{{ detail.planName }} · 配置 V{{ detail.planVersion }}</dd><dt>规则快照</dt><dd>{{ detail.rule.name }} V{{ detail.rule.version }}</dd><dt>应执行时间</dt><dd>{{ displayTime(detail.scheduledStart) }} — {{ displayTime(detail.deadline) }}</dd><dt>主执行人</dt><dd>{{ detail.personName }}</dd><dt>实际开始</dt><dd>{{ displayTime(detail.startedAt) }}</dd><dt>实际提交</dt><dd>{{ displayTime(detail.submittedAt) }}</dd></dl><p class="demo-note">下列位置、对象、检查项和参考条件来自任务生成时快照；规则或计划变更不会回写本次内容。</p><TaskResults :task="detail" /></template><template #footer><template v-if="detail && detail.status!=='已完成'"><p v-if="detail.personId!==personId" class="footer-note">当前演示身份不是本任务主执行人，仅可查看。可在列表选择与任务一致的演示身份。</p><el-button type="primary" :disabled="detail.personId!==personId" @click="execute(detail.id)">进入移动巡检演示</el-button></template><router-link v-else-if="detail" :to="{path:'/inspection/records',query:{task:detail.id}}"><el-button type="primary" plain>查看同源记录</el-button></router-link></template></el-drawer>
    <el-dialog v-model="mobile" title="移动端巡检预览（PC内演示）" width="min(520px,96vw)" class="ez-dialog inspection-editor mobile-editor" align-center append-to-body destroy-on-close><InspectionExecution v-if="mobile" :person-id="personId" :initial-task-id="mobileTaskId" /></el-dialog>
  </main>
</template>
<style scoped src="./inspection.css"></style>
